-- public.wall_needing(p_world uuid, p_cx integer, p_cy integer, p_range integer, p_holding text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.wall_needing(p_world uuid, p_cx integer, p_cy integer, p_range integer, p_holding text)
 RETURNS TABLE(dir text, x integer, y integer, item text)
 LANGUAGE sql
 STABLE
AS $function$
  select w.dir, w.x, w.y, e.key
  from wall w
  cross join lateral jsonb_each_text(w.needed) e
  where w.world_id = p_world and w.level = 0 and e.value::int > 0
    and greatest(abs(w.x - p_cx), abs(w.y - p_cy)) <= p_range
  order by (p_holding is not null and e.key = p_holding) desc,
           (w.x - p_cx) ^ 2 + (w.y - p_cy) ^ 2
  limit 1
$function$
